230	/**
231	 * THE iOS GUARD. This is the only place in the codebase permitted to read
232	 * acceleration off a DeviceMotionEvent.
233	 *
234	 * UNVERIFIED (iOS): assumes iOS exposes `accelerationIncludingGravity` but NOT
235	 * `acceleration`. Android exposes both, so an Android-only test can never catch
236	 * a regression that reintroduces `event.acceleration` — which would read
237	 * undefined on every iPhone. Keeping the read in one function is the guard.
238	 */
239	export function readAcceleration(event) {
240	  const a = event.accelerationIncludingGravity;
241	  if (!a || (a.x === null && a.y === null && a.z === null)) return null;
242	  return { x: a.x ?? 0, y: a.y ?? 0, z: a.z ?? 0 };
243	}
244	
245	export function readRotationRate(event) {
246	  const r = event.rotationRate;
247	  if (!r) return { alpha: 0, beta: 0, gamma: 0 };
248	  return { alpha: r.alpha ?? 0, beta: r.beta ?? 0, gamma: r.gamma ?? 0 };
249	}
