65	        /// has to mean straight *to the player looking at the TV*. With a hardcoded
66	        /// forward, a camera framed even slightly off-axis makes a dead-centre throw
67	        /// visibly drift to one side, and no amount of correct phone aiming fixes it —
68	        /// the player just learns the game is lying to them.
69	        ///
70	        /// Flattened onto the horizontal plane: only the heading matters here, since
71	        /// the launch pitch comes from SkipTuning.
72	        ///
73	        /// Captured once, from the aiming view. Reading it live would swing the arc
74	        /// around as the follow camera chases a rock downrange.
75	        /// </remarks>
76	        public Vector3 ThrowForward { get; private set; } = Vector3.forward;
77	
78	        private RelayClient _client;
79	        private LineRenderer _line;
80	        private Transform _ghost;
81	
82	        private readonly List<Vector3> _path = new(512);
83	
84	        private int _lastSeq = -1;
85	        private string _lastAimPlayer;
86	        private float _lastAimTime = -999f;
87	
88	        // Set while the arc is showing a throw that already happened rather than a
89	        // prediction of one that has not.
90	        private bool _showingThrow;
91	        private float _thrownPower, _thrownTiming, _thrownSpin;
92	
93	        private float _targetAim, _targetAttack, _targetRoll, _targetWindup;
94	        private float _curAim, _curAttack, _curRoll, _curWindup;
95	        private float _velAim, _velAttack, _velRoll, _velWindup;
96	
97	        private void Awake()
98	        {
99	            if (tuning == null) tuning = SkipTuning.CreateDefault();
100	            if (createPlaceholderScene) BuildPlaceholderScene();
101	            if (throwOrigin == null) throwOrigin = CreateOrigin();
102	
103	            // After BuildPlaceholderScene, which is what frames the camera.
104	            RefreshThrowForward();
105	
106	            BuildLine();
107	            BuildGhost();
108	        }
109	
110	        private void OnDestroy()
111	        {
112	            if (_client == null) return;
113	            _client.AimReceived -= OnAim;
114	            _client.ThrowReceived -= OnThrow;
115	        }
116	
117	        /// <summary>
118	        /// Redraw the arc from the throw that actually happened, and hold it there while
119	        /// it fades.
120	        /// </summary>
121	        /// <remarks>
122	        /// The throw is computed from the last sensor sample before release, while the
123	        /// arc was drawn from the most recent AIM frame smoothed over several more — so
124	        /// at the instant of release they are close but not identical. Snapping here
125	        /// means the final thing the player sees is the line the rock is on, not the
126	        /// line it was very nearly on, and it makes a mismatch between preview and
127	        /// throw visible instead of something to squint at frame by frame.
128	        /// </remarks>
129	        private void OnThrow(ThrowMessage message)
130	        {
131	            _targetAim = _curAim = message.aimDeg;
132	            _targetAttack = _curAttack = message.attackAngleDeg;
133	            _targetRoll = _curRoll = message.rollDeg;
134	            _velAim = _velAttack = _velRoll = 0f;
135	
136	            _thrownPower = message.power;
137	            _thrownTiming = message.timingQuality;
138	            _thrownSpin = message.spinRate;
139	            _showingThrow = true;
140	
141	            _lastAimTime = Time.time;
142	        }
143	
144	        private void Update()
145	        {
146	            EnsureBound();
147	
148	            HasSignal = Time.time - _lastAimTime <= staleAfterSeconds;
149	
150	            // Smooth every frame regardless of packet arrival — this is what turns
151	            // 20Hz of network data into something that reads as continuous motion.
152	            _curAim = Mathf.SmoothDampAngle(_curAim, _targetAim, ref _velAim, smoothTime);
153	            _curAttack = Mathf.SmoothDampAngle(_curAttack, _targetAttack, ref _velAttack, smoothTime);
154	            _curRoll = Mathf.SmoothDampAngle(_curRoll, _targetRoll, ref _velRoll, smoothTime);
155	            _curWindup = Mathf.SmoothDamp(_curWindup, _targetWindup, ref _velWindup, smoothTime);
156	
157	            _line.enabled = HasSignal;
158	            _ghost.gameObject.SetActive(HasSignal);
159	
160	            if (!HasSignal) return;
161	
162	            UpdateGhost();
163	            UpdateArc();
164	        }
165	
166	        private void EnsureBound()
167	        {
168	            // HasInstance, not Instance — Instance would create a RelayClient, and a
169	            // preview that conjures its own data source hides a real failure.
170	            if (_client != null || !RelayClient.HasInstance) return;
171	
172	            _client = RelayClient.Instance;
173	            _client.AimReceived += OnAim;
174	            _client.ThrowReceived += OnThrow;
175	        }
176	
177	        private void OnAim(AimMessage aim)
178	        {
179	            // Only the active player steers the preview; a stray frame from someone
180	            // else's phone must not yank the arc around.
181	            var active = TurnManager.HasInstance ? TurnManager.Instance.ActivePlayer : null;
182	            if (!string.IsNullOrEmpty(active) && aim.playerId != active) return;
183	
184	            // The sequence counter is per-phone and only advances while that phone is
185	            // gripping, so counts from different players are not comparable. Comparing
186	            // them against one shared value meant whoever had gripped the most locked
187	            // everyone else out: their successors' frames all arrived with a lower seq
188	            // and were silently dropped, so only one player in a session ever got an
189	            // aim preview. Reset the guard whenever the aiming player changes.
190	            if (aim.playerId != _lastAimPlayer)
191	            {
192	                _lastAimPlayer = aim.playerId;
193	                _lastSeq = -1;
194	            }
195	
196	            // Within one player, this is still the ordering guard it was meant to be:
197	            // TCP preserves order per socket, but a reconnect can interleave, and a
198	            // stale frame overwriting a newer one looks like a stutter.
199	            if (aim.seq <= _lastSeq) return;
200	            _lastSeq = aim.seq;
201	
202	            // First frame of a new aim, rather than a continuation of one in progress.
203	            // A throw still on screen also counts: the next gesture has begun, so the
204	            // arc must stop showing the previous throw and start tracking again.
205	            var reacquired = _showingThrow || Time.time - _lastAimTime > staleAfterSeconds;
206	            _showingThrow = false;
207	
208	            _targetAim = aim.aimDeg;
209	            _targetAttack = aim.attackAngleDeg;
210	            _targetRoll = aim.rollDeg;
211	            _targetWindup = aim.windup;
212	            _lastAimTime = Time.time;
213	
214	            if (!reacquired) return;
215	
216	            // Nothing was carried over from the last throw, so start exactly on the new
217	            // values instead of easing across from them. Smoothing in from a stale
218	            // target meant every turn opened by sweeping the arc over from wherever the
219	            // PREVIOUS player had been aiming, and spent the first fraction of a second
220	            // — a real share of the time the preview is on screen at all — showing a
221	            // line nobody had asked for.
222	            _curAim = _targetAim;
223	            _curAttack = _targetAttack;
224	            _curRoll = _targetRoll;
225	            _curWindup = _targetWindup;
226	            _velAim = _velAttack = _velRoll = _velWindup = 0f;
227	        }
228	
229	        private void UpdateArc()
230	        {
231	            // While predicting, power and timing are unknown, so the arc is drawn at a
232	            // nominal effort and promises a line rather than a landing spot. Once the
233	            // throw has actually happened they are known exactly, so the fading arc
234	            // switches to the real thing and traces the rock's own path.
235	            var launch = SkipPhysics.CreateLaunch(
236	                throwOrigin.position, ThrowForward,
237	                _showingThrow ? _thrownPower : previewPower,
238	                _showingThrow ? _thrownTiming : 1f,
239	                _curAim, _curAttack,
240	                _showingThrow ? _thrownSpin : previewSpin,
241	                RockStats.Default, tuning);
242	
243	            var final = SkipPhysics.Predict(launch, RockStats.Default, tuning, _path);
244	
245	            PredictedSkips = final.SkipCount;
246	            PredictedDistance = Vector3.Distance(throwOrigin.position, final.Position);
247	
248	            _line.positionCount = _path.Count;
249	            _line.SetPositions(_path.ToArray());
250	
251	            // Green when the angle is working, red when the stone is going to plough in.
252	            var health = Mathf.Clamp01(PredictedSkips / 5f);
253	            var colour = Color.Lerp(new Color(1f, 0.3f, 0.35f), new Color(0.35f, 1f, 0.6f), health);
254	            _line.startColor = colour;
255	            _line.endColor = new Color(colour.r, colour.g, colour.b, 0.15f);
256	        }
257	
258	        private void UpdateGhost()
259	        {
260	            _ghost.position = throwOrigin.position;
261	
262	            // Built on ThrowForward, not on world axes, so the ghost tilts about the
263	            // same heading the arc leaves along. Then pitch by the stone's face angle,
264	            // yaw by aim, roll by wrist tilt.
265	            _ghost.rotation = Quaternion.LookRotation(ThrowForward, Vector3.up)
266	                            * Quaternion.Euler(-_curAttack, _curAim, _curRoll);
267	
268	            var scale = Mathf.Lerp(1f, 1.35f, _curWindup);
269	            _ghost.localScale = new Vector3(0.45f * scale, 0.08f * scale, 0.45f * scale);
270	        }
271	
272	        // ---------------------------------------------------------------- scaffolding
273	
274	        /// <summary>
275	        /// Re-reads "straight ahead" from the main camera. Call after moving the aiming
276	        /// camera; the real lake scene will want this once its framing is authored.
277	        /// </summary>
278	        public void RefreshThrowForward()
279	        {
280	            var camera = Camera.main;
281	            if (camera == null) return;
282	
283	            var flattened = Vector3.ProjectOnPlane(camera.transform.forward, Vector3.up);
284	
285	            // A camera pointing straight down has no heading to inherit; keep the last
286	            // good value rather than collapsing the aim to a zero vector.
287	            if (flattened.sqrMagnitude < 1e-4f) return;
288	
289	            ThrowForward = flattened.normalized;
290	        }
291	
292	        private Transform CreateOrigin()
293	        {
294	            var origin = new GameObject("ThrowOrigin").transform;
295	            origin.position = new Vector3(0f, 1.2f, 0f);
296	            return origin;
297	        }
298	
299	        private void BuildLine()
300	        {
301	            var go = new GameObject("AimArc");
302	            go.transform.SetParent(transform, false);
303	
304	            _line = go.AddComponent<LineRenderer>();
305	            _line.widthMultiplier = 0.12f;
306	            _line.numCapVertices = 4;
307	            _line.useWorldSpace = true;
308	            _line.material = CreateUnlitMaterial(Color.white);
309	            _line.enabled = false;
310	        }
311	
312	        private void BuildGhost()
313	        {
314	            var ghost = GameObject.CreatePrimitive(PrimitiveType.Cube);
315	            ghost.name = "GhostRock";
316	            Destroy(ghost.GetComponent<Collider>());
317	            ghost.GetComponent<MeshRenderer>().material = CreateUnlitMaterial(new Color(0.9f, 0.92f, 1f));
318	            _ghost = ghost.transform;
319	            _ghost.SetParent(transform, false);
320	        }
321	
322	        private void BuildPlaceholderScene()
323	        {
324	            // Square, and starting at the player's feet rather than floating ahead of
325	            // them. A Unity plane is 10 units per unit of scale, so this is 200x200.
326	            var water = GameObject.CreatePrimitive(PrimitiveType.Plane);
327	            water.name = "PlaceholderWater";
328	            water.transform.position = new Vector3(0f, tuning.WaterY, 100f);
329	            water.transform.localScale = new Vector3(20f, 1f, 20f);
330	            Destroy(water.GetComponent<Collider>());
331	            water.GetComponent<MeshRenderer>().material = CreateUnlitMaterial(new Color(0.06f, 0.16f, 0.28f));
332	
333	            var camera = Camera.main;
334	            if (camera == null) return;
335	
336	            // Square on to the lake, looking straight down +Z with no yaw, pitch or
337	            // roll. Any rotation here is a rotation the player has to unconsciously
338	            // correct for: a camera even a few degrees off-axis makes a dead-centre
339	            // throw visibly drift, and ThrowForward inherits whatever tilt is left in.
340	            // Identity rotation is what makes "straight" mean the same thing to the
341	            // solver, the preview, and the person holding the phone.
342	            camera.transform.SetPositionAndRotation(
343	                new Vector3(0f, 3.5f, -9f), Quaternion.identity);
344	
345	            camera.backgroundColor = new Color(0.05f, 0.09f, 0.15f);
346	            camera.clearFlags = CameraClearFlags.SolidColor;
347	            camera.farClipPlane = 500f;
348	        }
349	
350	        /// <summary>Shader.Find is editor-friendly; these are scaffolding visuals only.</summary>
351	        private static Material CreateUnlitMaterial(Color colour)
352	        {
353	            var shader = Shader.Find("Sprites/Default")
354	                      ?? Shader.Find("Unlit/Color")
355	                      ?? Shader.Find("Standard");
356	
357	            return new Material(shader) { color = colour };
358	        }
359	    }
360	}
