224	// ---------------------------------------------------------------------------
225	// server
226	// ---------------------------------------------------------------------------
227	
228	// The controller page is served from this same origin on purpose. Motion sensors
229	// need a secure context, and an HTTPS page cannot open a plain ws:// socket — so
230	// splitting the page and the socket across two origins means fighting mixed
231	// content forever. One origin gives HTTPS and WSS together, and one tunnel
232	// (or one Fly app) covers both.
233	const STATIC_DIR = nodePath.resolve(__dirname, '..', 'controller');
234	
235	const CONTENT_TYPES = {
236	  '.html': 'text/html; charset=utf-8',
237	  '.js': 'text/javascript; charset=utf-8',
238	  '.css': 'text/css; charset=utf-8',
239	  '.json': 'application/json; charset=utf-8',
240	  '.svg': 'image/svg+xml',
241	  '.png': 'image/png',
242	  '.ico': 'image/x-icon',
243	};
244	
245	function serveStatic(req, res) {
246	  const requested = decodeURIComponent((req.url || '/').split('?')[0]);
247	  const relative = requested === '/' ? 'index.html' : requested.replace(/^\/+/, '');
248	  const resolved = nodePath.resolve(STATIC_DIR, relative);
249	
250	  // Refuse anything that escapes the static root.
251	  if (!resolved.startsWith(STATIC_DIR)) {
252	    res.writeHead(403).end('Forbidden');
253	    return;
254	  }
255	
256	  fs.readFile(resolved, (err, data) => {
257	    if (err) {
258	      res.writeHead(404, { 'Content-Type': 'text/plain' }).end('Not found');
259	      return;
260	    }
261	    const type = CONTENT_TYPES[nodePath.extname(resolved).toLowerCase()] || 'application/octet-stream';
262	    res.writeHead(200, { 'Content-Type': type, 'Cache-Control': 'no-cache' }).end(data);
263	  });
264	}
265	
266	/**
267	 * QR module matrix for an arbitrary string, as JSON.
268	 *
269	 * Returns the raw black/white grid rather than a PNG so the caller renders it at
270	 * whatever size it needs — Unity draws this on a TV, where a fixed-resolution
271	 * image would either band or blur. Rows are strings of '0'/'1' because Unity's
272	 * JsonUtility cannot deserialize nested arrays.
273	 */
274	function serveQr(req, res, query) {
275	  const data = query.get('data');
276	
277	  if (!data || data.length > MAX_QR_DATA_LENGTH) {
278	    res.writeHead(400, { 'Content-Type': 'application/json' })
279	      .end(JSON.stringify({ error: `data must be 1..${MAX_QR_DATA_LENGTH} characters` }));
280	    return;
281	  }
282	
283	  try {
284	    // Type 0 picks the smallest version that fits. Level M survives the glare and
285	    // off-angle scanning you get pointing a phone at a television.
286	    const qr = qrcode(0, 'M');
287	    qr.addData(data);
288	    qr.make();
289	
290	    const size = qr.getModuleCount();
291	    const rows = [];
292	    for (let row = 0; row < size; row++) {
293	      let bits = '';
294	      for (let col = 0; col < size; col++) bits += qr.isDark(row, col) ? '1' : '0';
295	      rows.push(bits);
296	    }
297	
298	    res.writeHead(200, { 'Content-Type': 'application/json', 'Cache-Control': 'no-cache' })
299	      .end(JSON.stringify({ size, rows }));
300	  } catch (err) {
301	    res.writeHead(400, { 'Content-Type': 'application/json' })
302	      .end(JSON.stringify({ error: String(err.message || err) }));
303	  }
304	}
305	
306	const httpServer = http.createServer((req, res) => {
307	  // Base is a formality — only the path and query are ever read.
308	  const url = new URL(req.url || '/', 'http://localhost');
309	
310	  if (url.pathname === '/health') {
311	    res.writeHead(200, { 'Content-Type': 'application/json' })
312	      .end(JSON.stringify({ ok: true, rooms: rooms.size }));
313	    return;
314	  }
315	
316	  if (url.pathname === '/qr') {
317	    serveQr(req, res, url.searchParams);
318	    return;
319	  }
320	
321	  serveStatic(req, res);
322	});
323	
324	const wss = new WebSocketServer({ server: httpServer, maxPayload: MAX_MESSAGE_BYTES });
325	
326	wss.on('connection', (ws) => {
327	  ws.meta = {
328	    role: null,
329	    roomCode: null,
330	    playerId: null,
331	    isAlive: true,
332	    rateWindowStart: Date.now(),
333	    rateCount: 0,
334	  };
335	
336	  ws.on('pong', () => {
337	    ws.meta.isAlive = true;
338	  });
339	
340	  ws.on('message', (raw) => {
341	    if (isRateLimited(ws.meta)) return; // drop silently; a flooding client gets no feedback loop
342	
343	    let data;
344	    try {
345	      data = JSON.parse(raw);
346	    } catch {
347	      // The prototype let this throw, which killed the whole process and every
348	      // other room with it. One bad client must never take down the server.
349	      sendError(ws, 'BAD_JSON', 'Message was not valid JSON.');
350	      return;
351	    }
352	
353	    if (!data || typeof data !== 'object' || typeof data.type !== 'string') {
354	      sendError(ws, 'BAD_MESSAGE', 'Message must be an object with a "type".');
355	      return;
356	    }
357	
358	    switch (data.type) {
359	      case 'CREATE_ROOM':
360	        handleCreateRoom(ws);
361	        return;
362	      case 'JOIN_ROOM':
363	        handleJoinRoom(ws, data);
364	        return;
365	      case 'PING':
366	        send(ws, { type: 'PONG' });
367	        return;
368	      default:
369	        if (ws.meta.role === 'player') relayToHost(ws, data);
370	        else if (ws.meta.role === 'host') relayToPlayers(ws, data);
371	        else sendError(ws, 'NOT_REGISTERED', 'Send CREATE_ROOM or JOIN_ROOM first.');
372	    }
373	  });
374	
375	  ws.on('close', () => {
376	    const { role, roomCode, playerId } = ws.meta;
377	    if (!roomCode) return;
378	
379	    const room = rooms.get(roomCode);
380	    if (!room) return;
381	
382	    if (role === 'host' && room.host === ws) {
383	      closeRoom(room, 'Host disconnected');
384	      return;
385	    }
386	
387	    if (role === 'player' && room.players.get(playerId) === ws) {
388	      room.players.delete(playerId);
389	      send(room.host, { type: 'PLAYER_LEFT', playerId });
390	      log(`room ${roomCode}: ${playerId} left (${room.players.size} players)`);
391	    }
392	  });
393	
394	  ws.on('error', (err) => log('socket error:', err.message));
395	});
396	
397	// Drop sockets that stopped responding — phones that lose signal often never
398	// send a clean close frame, which would otherwise leak room slots forever.
399	const heartbeat = setInterval(() => {
400	  for (const ws of wss.clients) {
401	    if (!ws.meta) continue;
402	    if (!ws.meta.isAlive) {
403	      ws.terminate();
404	      continue;
405	    }
406	    ws.meta.isAlive = false;
407	    ws.ping();
408	  }
409	}, HEARTBEAT_MS);
410	
411	// Rooms whose host vanished without a close frame would otherwise persist for
412	// the lifetime of the process.
413	const roomSweep = setInterval(() => {
414	  const now = Date.now();
415	  for (const room of [...rooms.values()]) {
416	    if (now - room.lastActivity > ROOM_IDLE_TIMEOUT_MS) {
417	      closeRoom(room, 'Room idle timeout');
418	    }
419	  }
420	}, ROOM_SWEEP_MS);
421	
422	wss.on('close', () => {
423	  clearInterval(heartbeat);
424	  clearInterval(roomSweep);
425	});
426	
427	function shutdown() {
428	  log('shutting down');
429	  clearInterval(heartbeat);
430	  clearInterval(roomSweep);
431	  for (const room of [...rooms.values()]) closeRoom(room, 'Server shutting down');
432	  wss.close(() => httpServer.close(() => process.exit(0)));
433	  setTimeout(() => process.exit(0), 3000).unref();
434	}
435	
436	process.on('SIGTERM', shutdown);
437	process.on('SIGINT', shutdown);
438	
439	httpServer.listen(PORT, () => {
440	  log(`Rock Skipping relay listening on :${PORT}`);
441	  log(`  controller page  http://localhost:${PORT}/`);
442	  log(`  websocket        ws://localhost:${PORT}/`);
443	  log(`  serving static from ${STATIC_DIR}`);
444	});
