1	/**
2	 * Controller app wiring: network + sensors + gesture + UI.
3	 *
4	 * TEST STATUS: verified on Android (Chrome). iOS paths are written from spec and
5	 * tagged `UNVERIFIED (iOS)` — see PLAN.md "Test device policy".
6	 */
7	
8	import { MotionSource, requestMotionPermission, isSecureContextOk } from './sensors.js';
9	import { ThrowController, ThrowState, ThrowGesture, setYawSign } from './throw.js';
10	import { RelayConnection, ConnectionStatus } from './net.js';
11	
12	const el = (id) => document.getElementById(id);
13	
14	const ui = {
15	  status: el('status'),
16	  joinScreen: el('joinScreen'),
17	  waitScreen: el('waitScreen'),
18	  throwScreen: el('throwScreen'),
19	  joinError: el('joinError'),
20	  nameInput: el('nameInput'),
21	  codeInput: el('codeInput'),
22	  joinBtn: el('joinBtn'),
23	  gripBtn: el('gripBtn'),
24	  throwHint: el('throwHint'),
25	  waitTitle: el('waitTitle'),
26	  waitDetail: el('waitDetail'),
27	  scores: el('scores'),
28	  throwResult: el('throwResult'),
29	  debug: el('debug'),
30	  debugToggle: el('debugToggle'),
31	};
32	
33	// Tunable from the URL (?gravityK=0.92) so the filter can be dialled in on a real
34	// phone without a redeploy. k controls how fast the gravity estimate adapts: too
35	// low and a slow swing leaks into the estimate and gets subtracted back out,
36	// flattening peak power; too high and it lags when the phone is re-oriented.
37	// The right value depends on the device's real sample rate — tune on hardware.
38	const GRAVITY_K = Number(new URLSearchParams(location.search).get('gravityK')) || 0.8;
39	
40	// Which way device heading maps onto game yaw. Both are clockwise-from-above, so the
41	// default is +1. Overridable per-device — open the controller with ?yawSign=-1 on a
42	// handset that steers backwards, to find out whether the platforms disagree without a
43	// redeploy. See the comment on setYawSign in throw.js.
44	const YAW_SIGN = Number(new URLSearchParams(location.search).get('yawSign'));
45	if (YAW_SIGN === 1 || YAW_SIGN === -1) setYawSign(YAW_SIGN);
46	
47	// Press-and-hold by default. Tap-swing-tap was tried in playtest and reverted: it
48	// shortened the aiming phase rather than sharpening the release, because the hold is
49	// what gives the player a window to see the arc and adjust before committing.
50	// ?gesture=tap opts back into it for comparison.
51	const GESTURE = new URLSearchParams(location.search).get('gesture') === ThrowGesture.TAP
52	  ? ThrowGesture.TAP
53	  : ThrowGesture.HOLD;
54	
55	const GESTURE_LABELS = {
56	  [ThrowGesture.TAP]: { idle: 'TAP TO AIM', armed: 'TAP TO THROW',
57	                        hint: 'Point your phone at the lake, tap, swing, then tap again to let go.' },
58	  [ThrowGesture.HOLD]: { idle: 'HOLD', armed: 'SWING!',
59	                         hint: 'Point your phone at the lake, hold, swing, and let go.' },
60	};
61	
62	const motion = new MotionSource({ gravityK: GRAVITY_K });
63	let connection = null;
64	let lastThrow = null;
65	let myPlayerId = '';
66	
67	function showScreen(name) {
68	  for (const screen of [ui.joinScreen, ui.waitScreen, ui.throwScreen]) {
69	    screen.classList.remove('active');
70	  }
71	  ({ join: ui.joinScreen, wait: ui.waitScreen, throw: ui.throwScreen })[name].classList.add('active');
72	}
73	
74	function setStatus(text, kind = '') {
75	  ui.status.textContent = text;
76	  ui.status.className = kind;
77	}
78	
79	// ---------------------------------------------------------------- gesture
80	
81	const thrower = new ThrowController(motion, {
82	  gesture: GESTURE,
83	  onAim: (payload) => connection?.send(payload),
84	  onThrow: (payload) => {
85	    connection?.send(payload);
86	    lastThrow = payload;
87	    ui.throwResult.textContent =
88	      `Power ${(payload.power * 100).toFixed(0)}% · Timing ${(payload.timingQuality * 100).toFixed(0)}%` +
89	      (payload.simulated ? ' · simulated (no motion sensors)' : '');
90	  },
91	  onStateChange: (state) => {
92	    const armed = state === ThrowState.GRIPPED;
93	    ui.gripBtn.classList.toggle('held', armed);
94	    ui.gripBtn.textContent = GESTURE_LABELS[GESTURE][armed ? 'armed' : 'idle'];
95	  },
96	  onExpire: () => {
97	    ui.throwResult.textContent = 'Took too long — tap to aim again.';
98	  },
99	});
100	
101	/** Android only — iOS support for navigator.vibrate is unreliable, so this is a bonus. */
102	function confirmThrow(descriptor) {
103	  if (descriptor && navigator.vibrate) navigator.vibrate(30);
104	  return descriptor;
105	}
106	
107	function bindGrip() {
108	  const start = (event) => {
109	    event.preventDefault(); // stop the tap turning into a scroll or a zoom
110	    thrower.grip();
111	  };
112	  const end = (event) => {
113	    event.preventDefault();
114	    confirmThrow(thrower.release());
115	  };
116	
117	  if (GESTURE === ThrowGesture.TAP) {
118	    // Bound to the press, not the lift. The press is the instant the player chose;
119	    // waiting for touchend would add however long their thumb takes to come back up
120	    // to a value the physics reads as the exact moment of release.
121	    const tap = (event) => {
122	      event.preventDefault();
123	      confirmThrow(thrower.tap());
124	    };
125	
126	    ui.gripBtn.addEventListener('touchstart', tap, { passive: false });
127	    ui.gripBtn.addEventListener('mousedown', tap);
128	
129	    // Deliberately no touchcancel handler: in tap mode the finger is not held, so a
130	    // cancelled touch is not the player abandoning the throw.
131	    return;
132	  }
133	
134	  ui.gripBtn.addEventListener('touchstart', start, { passive: false });
135	  ui.gripBtn.addEventListener('touchend', end, { passive: false });
136	  ui.gripBtn.addEventListener('touchcancel', () => thrower.cancel());
137	
138	  // Mouse fallback so the gesture can be exercised on a desktop browser.
139	  ui.gripBtn.addEventListener('mousedown', start);
140	  ui.gripBtn.addEventListener('mouseup', end);
141	}
142	
143	// ---------------------------------------------------------------- messages
144	
145	function handleMessage(message) {
146	  switch (message.type) {
147	    case 'JOINED':
148	      myPlayerId = message.playerId;
149	      setStatus(`Connected as ${myPlayerId}`, 'ok');
150	      showScreen('wait');
151	      motion.start();
152	      requestWakeLock();
153	      break;
154	
155	    case 'ERROR':
156	      ui.joinError.textContent = message.message ?? 'Something went wrong.';
157	      showScreen('join');
158	      ui.joinBtn.disabled = false;
159	      break;
160	
161	    case 'TURN':
162	      if (message.yourTurn) {
163	        ui.throwResult.textContent = '';
164	        showScreen('throw');
165	      } else {
166	        thrower.cancel();
167	        showScreen('wait');
168	      }
169	      break;
170	
171	    case 'SPECTATE':
172	      renderSpectate(message);
173	      break;
174	
175	    case 'ROOM_CLOSED':
176	      setStatus('Game ended', 'bad');
177	      thrower.cancel();
178	      showScreen('join');
179	      ui.joinBtn.disabled = false;
180	      break;
181	  }
182	}
183	
184	/** Highest scorer, or null when nobody leads outright. */
185	function leader(scores) {
186	  const entries = Object.entries(scores ?? {});
187	  if (entries.length === 0) return null;
188	
189	  entries.sort((a, b) => b[1] - a[1]);
190	  if (entries.length > 1 && entries[0][1] === entries[1][1]) return null; // tied
191	  return entries[0][0];
192	}
193	
194	function renderSpectate(message) {
195	  if (thrower.state === ThrowState.GRIPPED) return; // don't yank the screen mid-throw
196	
197	  // Without the phase, every idle moment reads "Waiting for the next turn" — including
198	  // the lobby before anything has started and the results screen after it has ended.
199	  const phase = message.phase ?? 'PLAYING';
200	
201	  if (phase === 'LOBBY') {
202	    ui.waitTitle.textContent = 'Waiting for the game to start';
203	    ui.waitDetail.textContent = 'You are in. Watch the TV.';
204	  } else if (phase === 'RESULTS') {
205	    const winner = leader(message.scores);
206	    ui.waitTitle.textContent = 'Final scores';
207	    ui.waitDetail.textContent = winner
208	      ? (winner === myPlayerId ? 'You win!' : `${winner} wins`)
209	      : 'It is a tie.';
210	  } else {
211	    ui.waitTitle.textContent = message.activePlayer
212	      ? `${message.activePlayer} is throwing`
213	      : 'Waiting for the next turn';
214	
215	    const parts = [];
216	    if (message.round && message.totalRounds) {
217	      parts.push(`Round ${message.round}/${message.totalRounds}`);
218	    }
219	    if (message.rockName) parts.push(message.rockName);
220	    if (typeof message.liveSkips === 'number') parts.push(`${message.liveSkips} skips`);
221	    if (typeof message.liveDistance === 'number') parts.push(`${message.liveDistance.toFixed(1)} m`);
222	    ui.waitDetail.textContent = parts.join(' · ') || 'Watch the TV.';
223	  }
224	
225	  ui.scores.innerHTML = '';
226	  for (const [player, score] of Object.entries(message.scores ?? {})) {
227	    const row = document.createElement('div');
228	    row.className = 'score-row' + (player === message.activePlayer ? ' active' : '');
229	    row.innerHTML = `<span>${player}</span><span>${score}</span>`;
230	    ui.scores.appendChild(row);
231	  }
232	}
233	
234	// ---------------------------------------------------------------- join
235	
236	async function join() {
237	  const name = ui.nameInput.value.trim();
238	  const code = ui.codeInput.value.trim().toUpperCase();
239	
240	  if (!name || code.length !== 4) {
241	    ui.joinError.textContent = 'Enter your name and the 4-letter code.';
242	    return;
243	  }
244	
245	  // Motion sensors are restricted to secure contexts. Over plain HTTP on a LAN IP
246	  // this fails on every modern phone, so say so plainly instead of appearing to
247	  // work and then producing dead sensors.
248	  if (!isSecureContextOk()) {
249	    ui.joinError.textContent = 'Needs HTTPS. Open this page over https:// or localhost.';
250	    return;
251	  }
252	
253	  ui.joinBtn.disabled = true;
254	  ui.joinError.textContent = '';
255	
256	  // UNVERIFIED (iOS): must be called inside the user gesture that is this tap.
257	  // Deferring it behind an await of anything else loses gesture context and iOS
258	  // rejects the request. Android has no prompt and returns granted immediately.
259	  const permission = await requestMotionPermission();
260	  if (!permission.granted) {
261	    ui.joinError.textContent = 'Motion access denied. Enable it and reload.';
262	    ui.joinBtn.disabled = false;
263	    return;
264	  }
265	
266	  if (!connection) {
267	    connection = new RelayConnection({
268	      onMessage: handleMessage,
269	      onStatus: (status) => {
270	        if (status === ConnectionStatus.RECONNECTING) setStatus('Reconnecting…', 'bad');
271	        else if (status === ConnectionStatus.CONNECTING) setStatus('Connecting…');
272	      },
273	    });
274	    connection.connect();
275	  }
276	
277	  const waitForOpen = setInterval(() => {
278	    if (connection.status === ConnectionStatus.CONNECTED || connection.status === ConnectionStatus.JOINED) {
279	      clearInterval(waitForOpen);
280	      connection.joinRoom(code, name);
281	    }
282	  }, 100);
283	}
284	
285	// ---------------------------------------------------------------- misc
286	
287	async function requestWakeLock() {
288	  // Best effort. Keeps the screen alive between turns so players aren't unlocking
289	  // their phone every round. Unsupported on some browsers; harmless when it fails.
290	  try {
291	    if ('wakeLock' in navigator) await navigator.wakeLock.request('screen');
292	  } catch { /* ignore */ }
293	}
294	
295	function tryLockPortrait() {
296	  // Best effort only — most browsers refuse outside fullscreen. sensors.js
297	  // compensates for screen rotation regardless, which is the real fix.
298	  try { screen.orientation?.lock?.('portrait').catch(() => {}); } catch { /* ignore */ }
299	}
300	
301	function updateDebug() {
302	  if (!ui.debug.classList.contains('visible')) return;
303	  const s = motion.latest;
304	  ui.debug.textContent = [
305	    `state    ${thrower.state}   seq ${thrower.seq}`,
306	    `socket   ${connection?.status ?? 'not connected'}`,
307	    `calib    ${motion.hasReference() ? 'set' : 'none'}`,
308	    `heading  ${motion.headingDeg === null ? 'none' : motion.headingDeg.toFixed(1)}` +
309	      `   turn ${motion.headingRateDegPerSec.toFixed(0)}°/s`,
310	    s ? `dYaw ${s.dYaw.toFixed(1).padStart(7)}  dB ${s.dBeta.toFixed(1).padStart(7)}  dG ${s.dGamma.toFixed(1).padStart(7)}`
311	      : 'no samples yet — is this page on HTTPS?',
312	    s ? `power ${s.power.toFixed(2).padStart(6)} m/s²   samples ${motion.buffer.length}   ` +
313	        `${motion.sampleHz.toFixed(0)}Hz   k=${GRAVITY_K}` : '',
314	    lastThrow
315	      ? `throw  pow ${lastThrow.power.toFixed(2)} tim ${lastThrow.timingQuality.toFixed(2)} aim ${lastThrow.aimDeg.toFixed(0)} atk ${lastThrow.attackAngleDeg.toFixed(0)} spin ${lastThrow.spinRate.toFixed(0)}`
316	      : 'no throw yet',
317	  ].join('\n');
318	}
319	
320	function init() {
321	  const params = new URLSearchParams(location.search);
322	  const prefill = params.get('room');
323	  if (prefill) ui.codeInput.value = prefill.toUpperCase();
324	
325	  // The markup ships the hold-mode wording; both are owned here so they cannot
326	  // drift from whichever gesture is actually bound.
327	  ui.throwHint.textContent = GESTURE_LABELS[GESTURE].hint;
328	  ui.gripBtn.textContent = GESTURE_LABELS[GESTURE].idle;
329	
330	  ui.joinBtn.addEventListener('click', join);
331	  ui.debugToggle.addEventListener('click', () => ui.debug.classList.toggle('visible'));
332	  bindGrip();
333	  tryLockPortrait();
334	
335	  if (!isSecureContextOk()) {
336	    setStatus('Insecure context — sensors will not work', 'bad');
337	  } else {
338	    setStatus('Ready to join');
339	  }
340	
341	  setInterval(updateDebug, 100);
342	  document.addEventListener('visibilitychange', () => {
343	    if (document.visibilityState === 'visible') requestWakeLock();
344	  });
345	}
346	
347	init();
