7	namespace Managers
8	{
9	    /// <summary>
10	    /// Owns every point value in the game. Gameplay code publishes events describing
11	    /// what happened; this is the only place that decides what those are worth, so
12	    /// retuning scoring never touches physics or turn logic.
13	    /// </summary>
14	    public class ScoreManager : SingletonBase<ScoreManager>
15	    {
16	        [Header("Point values")]
17	        [SerializeField] private int pointsPerSkip = 10;
18	        [SerializeField] private int pointsPerRing = 50;
19	        [SerializeField] private int pointsPerMetre = 1;
20	
21	        private readonly Dictionary<string, int> _scores = new();
22	
23	        // Skips and rings arrive mid-flight, before we know the throw completed.
24	        // They're banked here and committed to the player on ThrowCompletedEvent.
25	        private int _pendingThrowPoints;
26	
27	        public IReadOnlyDictionary<string, int> Scores => _scores;
28	
29	        protected override void Awake()
30	        {
31	            persistBetweenScenes = true;
32	            base.Awake();
33	
34	            EventManager.Instance?.Subscribe<SkipOccurredEvent>(this, OnSkipOccurred);
35	            EventManager.Instance?.Subscribe<RingPassedEvent>(this, OnRingPassed);
36	            EventManager.Instance?.Subscribe<ThrowCompletedEvent>(this, OnThrowCompleted);
37	        }
38	
39	        private void OnSkipOccurred(SkipOccurredEvent e)
40	        {
41	            _pendingThrowPoints += pointsPerSkip;
42	        }
43	
44	        private void OnRingPassed(RingPassedEvent e)
45	        {
46	            _pendingThrowPoints += pointsPerRing;
47	        }
48	
49	        private void OnThrowCompleted(ThrowCompletedEvent e)
50	        {
51	            var total = _pendingThrowPoints + Mathf.RoundToInt(e.Distance * pointsPerMetre);
52	            _pendingThrowPoints = 0;
53	
54	            if (string.IsNullOrEmpty(e.PlayerId))
55	                return;
56	
57	            _scores.TryGetValue(e.PlayerId, out var current);
58	            _scores[e.PlayerId] = current + total;
59	        }
60	
61	        public int GetScore(string playerId)
62	        {
63	            _scores.TryGetValue(playerId, out var score);
64	            return score;
65	        }
66	
67	        public void ResetScores()
68	        {
69	            _scores.Clear();
70	            _pendingThrowPoints = 0;
71	        }
72	
73	        protected override void OnDestroy()
74	        {
75	            EventManager.Instance?.UnsubscribeFromAllEvents(this);
76	            base.OnDestroy();
77	        }
78	    }
79	}
