356	  // Minimal stand-ins: enough surface for grip()/release(), no browser needed.
357	  const makeMotion = (latest, samples) => ({
358	    latest,
359	    buffer: { toArray: () => samples, clear() {} },
360	    calibrate() {},
361	  });
362	
363	  const realSwing = [];
364	  for (let i = 0; i <= 10; i++) realSwing.push(makeSample(i * 10, i * 3));
365	
366	  // A device with sensors and a genuine swing: the measured throw must win.
367	  {
368	    const sent = [];
369	    const c = new ThrowController(makeMotion(realSwing[10], realSwing), {
370	      onThrow: (p) => sent.push(p),
371	      aimHz: 1000,
372	    });
373	    c.grip();
374	    const d = c.release();
375	    check('a real swing produces a measured throw, not a simulated one',
376	      sent.length === 1 && !sent[0].simulated && d.sampleCount === realSwing.length);
377	  }
378	
379	  // A device with sensors but a limp gesture: still a fumble. Falling back here
380	  // would turn every pocket bump on a real phone into a throw.
